UPDATE site_page SET content = '{"headline":"Termos de Serviço – PLANTAHUB","subheadline":null,"intro":"Ao acessar ou utilizar nossa plataforma, você concorda integralmente com estes Termos de Serviço. Caso não concorde com qualquer condição aqui descrita, recomendamos que não utilize nossos serviços.","sections":[{"key":null,"title":"1. Sobre o PlantaHUB","body":"O PlantaHUB é uma plataforma digital que comercializa projetos arquitetônicos e complementares em formato digital (BIM, DWG, PDF), destinados a uso técnico e profissional, conforme descrito em cada produto.","items":[]},{"key":null,"title":"2. Elegibilidade","body":"Para utilizar a plataforma, o usuário declara:","items":[{"title":null,"text":"Ter pelo menos 18 anos ou capacidade legal;","bullets":[]},{"title":null,"text":"Fornecer informações verdadeiras, completas e atualizadas;","bullets":[]},{"title":null,"text":"Utilizar os conteúdos de forma lícita.","bullets":[]}]},{"key":null,"title":"3. Cadastro e Conta","body":null,"items":[{"title":null,"text":"O usuário é responsável pela confidencialidade de suas credenciais;","bullets":[]},{"title":null,"text":"O PlantaHUB não se responsabiliza por acessos indevidos causados por negligência do usuário;","bullets":[]},{"title":null,"text":"Reservamo-nos o direito de suspender ou encerrar contas em caso de violação destes termos.","bullets":[]}]},{"key":null,"title":"4. Produtos Digitais","body":null,"items":[{"title":null,"text":"Todos os produtos são digitais e disponibilizados para download imediato, conforme descrito na página do produto;","bullets":[]},{"title":null,"text":"Não há envio físico de materiais;","bullets":[]},{"title":null,"text":"Os arquivos disponibilizados seguem as especificações técnicas informadas.","bullets":[]}]},{"key":null,"title":"5. Licença de Uso","body":"Ao adquirir um produto no PlantaHUB, o usuário recebe uma licença de uso não exclusiva, intransferível e limitada, destinada a: É expressamente proibido:","items":[{"title":null,"text":"Uso pessoal ou profissional;","bullets":[]},{"title":null,"text":"Execução de obra ou estudo técnico.","bullets":[]},{"title":null,"text":"Revender, sublicenciar ou redistribuir os arquivos;","bullets":[]},{"title":null,"text":"Disponibilizar os projetos em plataformas públicas ou privadas;","bullets":[]},{"title":null,"text":"Alterar os arquivos para fins de comercialização.","bullets":[]}]},{"key":null,"title":"6. Personalização de Projetos","body":"Quando oferecida, a personalização:","items":[{"title":null,"text":"Possui escopo limitado;","bullets":[]},{"title":null,"text":"Não inclui novo projeto autoral completo, salvo contratação específica;","bullets":[]},{"title":null,"text":"Pode ter prazos e condições próprias.","bullets":[]}]},{"key":null,"title":"7. Pagamentos","body":null,"items":[{"title":null,"text":"Os pagamentos são processados por gateways externos;","bullets":[]},{"title":null,"text":"O acesso ao download ocorre após a confirmação do pagamento;","bullets":[]},{"title":null,"text":"O PlantaHUB não armazena dados bancários ou de cartão.","bullets":[]}]},{"key":null,"title":"8. Política de Reembolso","body":"Por se tratar de conteúdo digital com acesso imediato, não realizamos reembolsos após o download, conforme o art. 49 do Código de Defesa do Consumidor, salvo exceções legais.","items":[]},{"key":null,"title":"9. Propriedade Intelectual","body":"Todos os conteúdos, marcas, layouts, textos, imagens e projetos são de propriedade do PlantaHUB ou de seus licenciantes, protegidos pela legislação vigente.","items":[]},{"key":null,"title":"10. Limitação de Responsabilidade","body":"O PlantaHUB não se responsabiliza por:","items":[{"title":null,"text":"Uso inadequado dos projetos;","bullets":[]},{"title":null,"text":"Execução da obra sem acompanhamento técnico profissional;","bullets":[]},{"title":null,"text":"Adequações legais exigidas por legislações municipais ou estaduais.","bullets":[]}]},{"key":null,"title":"11. Modificações","body":"O PlantaHUB pode atualizar estes Termos a qualquer momento. Recomenda-se a revisão periódica.","items":[]},{"key":null,"title":"12. Foro","body":"Fica eleito o foro da comarca do domicílio do consumidor, nos termos da legislação brasileira.","items":[]}],"faq":[],"ctaTitle":null,"ctaSubtitle":null,"ctaLabel":null,"ctaHref":null}'::jsonb WHERE slug = 'termos';

UPDATE site_page SET content = '{"headline":"Política de Privacidade – PLANTAHUB","subheadline":null,"intro":"O PlantaHUB respeita a sua privacidade e está comprometido com a proteção dos dados pessoais, em conformidade com a Lei Geral de Proteção de Dados (LGPD – Lei nº 13.709/2018).","sections":[{"key":null,"title":"1. Dados Coletados","body":"Podemos coletar:","items":[{"title":null,"text":"Nome completo;","bullets":[]},{"title":null,"text":"E-mail;","bullets":[]},{"title":null,"text":"CPF/CNPJ (quando necessário para emissão fiscal);","bullets":[]},{"title":null,"text":"Dados de navegação (IP, cookies, páginas acessadas);","bullets":[]},{"title":null,"text":"Informações de pagamento (processadas por terceiros).","bullets":[]}]},{"key":null,"title":"2. Finalidade do Tratamento","body":"Os dados são utilizados para:","items":[{"title":null,"text":"Criar e gerenciar contas;","bullets":[]},{"title":null,"text":"Processar compras e liberar downloads;","bullets":[]},{"title":null,"text":"Emitir documentos fiscais;","bullets":[]},{"title":null,"text":"Enviar comunicações transacionais;","bullets":[]},{"title":null,"text":"Melhorar a experiência do usuário.","bullets":[]}]},{"key":null,"title":"3. Compartilhamento de Dados","body":"Seus dados poderão ser compartilhados apenas com: Nunca vendemos ou comercializamos dados pessoais.","items":[{"title":null,"text":"Gateways de pagamento;","bullets":[]},{"title":null,"text":"Plataformas de hospedagem e infraestrutura;","bullets":[]},{"title":null,"text":"Autoridades legais, quando exigido por lei.","bullets":[]}]},{"key":null,"title":"4. Cookies","body":"Utilizamos cookies para: O usuário pode gerenciar cookies nas configurações do navegador.","items":[{"title":null,"text":"Funcionalidade da plataforma;","bullets":[]},{"title":null,"text":"Análise de desempenho;","bullets":[]},{"title":null,"text":"Melhoria contínua da experiência do usuário.","bullets":[]}]},{"key":null,"title":"5. Armazenamento e Segurança","body":"Adotamos medidas técnicas e administrativas para proteger os dados contra acessos não autorizados, vazamentos ou usos indevidos.","items":[]},{"key":null,"title":"6. Direitos do Titular","body":"Você pode, a qualquer momento: As solicitações podem ser feitas pelo canal oficial de contato do PlantaHUB.","items":[{"title":null,"text":"Solicitar acesso aos seus dados;","bullets":[]},{"title":null,"text":"Corrigir informações;","bullets":[]},{"title":null,"text":"Solicitar exclusão ou anonimização;","bullets":[]},{"title":null,"text":"Revogar consentimentos.","bullets":[]}]},{"key":null,"title":"7. Retenção de Dados","body":"Os dados serão armazenados apenas pelo tempo necessário para cumprir as finalidades legais, contratuais e regulatórias.","items":[]},{"key":null,"title":"8. Alterações nesta Política","body":"Esta Política pode ser atualizada a qualquer momento. Recomendamos a consulta periódica.","items":[]},{"key":null,"title":"9. Contato","body":"Para dúvidas, solicitações ou reclamações sobre privacidade, entre em contato pelos canais oficiais do PlantaHUB.","items":[]}],"faq":[],"ctaTitle":null,"ctaSubtitle":null,"ctaLabel":null,"ctaHref":null}'::jsonb WHERE slug = 'privacidade';

UPDATE site_page SET content = '{"headline":"Perguntas frequentes sobre compras, biblioteca, downloads e parcerias","subheadline":null,"intro":"Reunimos aqui as dúvidas mais comuns para ajudar clientes e parceiros a entender melhor como a PlantaHUB funciona.","sections":[],"faq":[{"category":"Compras","question":"Como funciona a compra de uma planta?","answer":"Você escolhe o produto, seleciona os tipos de planta desejados e conclui o pedido. Após o pagamento, os arquivos ficam disponíveis na sua biblioteca para download."},{"category":"Compras","question":"Posso comprar apenas algumas disciplinas do projeto?","answer":"Sim. A Plataforma permite adquirir somente os plan types desejados, como arquitetônica, hidráulica, elétrica, estrutural ou paisagística, conforme disponibilidade do produto."},{"category":"Biblioteca","question":"Onde encontro meus arquivos após a compra?","answer":"Todos os itens adquiridos ficam disponíveis na sua biblioteca. Lá você pode acessar cada tipo de planta individualmente, visualizar os arquivos liberados e iniciar os downloads."},{"category":"Downloads","question":"Posso baixar vários arquivos de uma vez?","answer":"Sim. A biblioteca permite selecionar várias plantas adquiridas e gerar um bundle ZIP com os arquivos correspondentes para facilitar o download em lote."},{"category":"Conta","question":"Preciso completar meu perfil para comprar?","answer":"Sim. Algumas informações obrigatórias de perfil são exigidas antes de finalizar a compra, para garantir segurança, rastreabilidade e consistência no fluxo da plataforma."},{"category":"Parcerias","question":"Como posso vender minhas plantas na PlantaHUB?","answer":"Você pode acessar a página Trabalhe Conosco e enviar seu portfólio para análise. Nossa equipe avalia os materiais e negocia a margem de venda conforme o modelo de parceria."},{"category":"Suporte","question":"O que faço se um arquivo não estiver disponível?","answer":"Caso um item adquirido não esteja disponível para download, entre em contato com o suporte da plataforma para verificação e regularização do material."}],"ctaTitle":null,"ctaSubtitle":null,"ctaLabel":null,"ctaHref":null}'::jsonb WHERE slug = 'faq';

UPDATE site_page SET content = '{"headline":"Arquitetura impulsionada por tecnologia","subheadline":"SOBRE A PLANTAHUB","intro":"Transformamos conhecimento arquitetônico em soluções digitais escaláveis para quem projeta, constrói e vive o ambiente construído.","sections":[{"key":"manifesto","title":"Manifesto da Marca","body":"Acreditamos que construir não precisa ser lento, caro ou desconectado da tecnologia.","items":[{"title":"Simplificar a complexidade","text":null,"bullets":[]},{"title":"Reduzir tempo","text":null,"bullets":[]},{"title":"Otimizar custo","text":null,"bullets":[]}]},{"key":"proposito","title":null,"body":"Existimos para transformar conhecimento arquitetônico em soluções digitais escaláveis, unindo construção, tecnologia e sustentabilidade.","items":[{"title":"Excelência Técnica","text":null,"bullets":[]},{"title":"Conformidade Legal","text":null,"bullets":[]},{"title":"Responsabilidade Ecológica","text":null,"bullets":[]}]},{"key":"identidade","title":null,"body":null,"items":[{"title":"Missão","text":null,"bullets":[]},{"title":"Visão","text":null,"bullets":[]},{"title":"Valores","text":null,"bullets":["Precisão técnica","Inovação acessível","Práticas sustentáveis","Confiança profissional"]}]},{"key":"pilares","title":"Três Pilares de Integração","body":"Onde construção, tecnologia e sustentabilidade convergem","items":[{"title":"Construção","text":null,"bullets":["Profissionais certificados","Conformidade regulatória","Precisão técnica"]},{"title":"Tecnologia","text":null,"bullets":["Entrega imediata","Marketplace digital","Plataforma escalável"]},{"title":"Sustentabilidade","text":null,"bullets":["Otimização de recursos","Design eco-consciente","Menos desperdício"]}]},{"key":"conformidade","title":"Conformidade Profissional & Certificação","body":"Cada planta na PLANTAHUB é pensada para atender padrões profissionais e requisitos regulatórios.","items":[{"title":"Certificação CAU","text":null,"bullets":[]},{"title":"Aprovado para conformidade","text":null,"bullets":[]},{"title":"Conformidade legal","text":null,"bullets":[]}]},{"key":"time","title":"Humanizado. Profissional. Confiável.","body":"Por trás de cada planta existe um time de profissionais experientes comprometidos em combinar décadas de experiência em arquitetura com tecnologia de ponta.","items":[]}],"faq":[],"ctaTitle":"Pronto para construir com confiança?","ctaSubtitle":"Junte-se a milhares de profissionais e clientes que confiam na PLANTAHUB.","ctaLabel":"Ver produtos","ctaHref":"/produtos"}'::jsonb WHERE slug = 'sobre';

UPDATE site_page SET content = '{"headline":"Publique suas plantas na PlantaHUB e transforme seus projetos em novas oportunidades de venda","subheadline":null,"intro":"Estamos em busca de arquitetos, projetistas e parceiros que desejam comercializar plantas com organização, alcance digital e negociação transparente de margem.","sections":[{"key":"beneficios","title":null,"body":null,"items":[{"title":"Parceria comercial","text":"Publique seus projetos na PlantaHUB e negocie uma margem de venda justa para cada planta comercializada.","bullets":[]},{"title":"Mais alcance para seus projetos","text":"Sua planta pode ser encontrada por clientes que buscam soluções arquitetônicas prontas, com exposição contínua dentro da plataforma.","bullets":[]},{"title":"Distribuição organizada","text":"Centralizamos o catálogo, o acesso do cliente e o fluxo de entrega digital, tornando a venda mais profissional e escalável.","bullets":[]}]},{"key":"como-funciona","title":"Como funciona a parceria","body":"Nosso processo foi pensado para facilitar a entrada de novos parceiros e garantir consistência no catálogo da plataforma.","items":[{"title":"Envie seu portfólio","text":"Compartilhe exemplos das suas plantas, estilos de projeto, informações técnicas e materiais que representem a qualidade do seu trabalho.","bullets":[]},{"title":"Analisamos a compatibilidade","text":"Nossa equipe avalia o potencial comercial, a organização dos arquivos e o alinhamento dos seus projetos com o padrão da plataforma.","bullets":[]},{"title":"Negociamos a parceria","text":"Definimos juntos a margem de venda, regras de publicação, critérios de atualização e os formatos dos arquivos comercializados.","bullets":[]},{"title":"Publicamos seus projetos","text":"Depois da aprovação, sua coleção entra no catálogo e passa a ficar disponível para clientes da PlantaHUB.","bullets":[]}]},{"key":"requisitos","title":"O que esperamos receber","body":null,"items":[{"title":null,"text":"Plantas organizadas por disciplina ou categoria técnica","bullets":[]},{"title":null,"text":"Arquivos com nomenclatura clara e estrutura profissional","bullets":[]},{"title":null,"text":"Projetos autorais ou com autorização formal de comercialização","bullets":[]},{"title":null,"text":"Material de apresentação com boa qualidade visual","bullets":[]}]}],"faq":[],"ctaTitle":"Envie seu portfólio","ctaSubtitle":"Nossa equipe avalia os materiais e retorna com a proposta de parceria.","ctaLabel":"Falar com parcerias","ctaHref":null}'::jsonb WHERE slug = 'trabalhe-conosco';

UPDATE site_page SET content = '{"headline":"Vamos conversar sobre seu projeto","subheadline":null,"intro":"Seja para dúvidas sobre compras, suporte técnico, parcerias ou personalizações, nossa equipe está pronta para ajudar com rapidez e clareza.","sections":[{"key":"formulario","title":"Envie uma mensagem","body":"Responderemos no menor prazo possível.","items":[]}],"faq":[],"ctaTitle":null,"ctaSubtitle":null,"ctaLabel":null,"ctaHref":null}'::jsonb WHERE slug = 'contato';

